fn main() {
    // member가 true면 회원이에요.
    // 채점은 이 값을 false로 바꿔서도 실행해요.
    let member = true;
    // 이 줄은 if 밖에 있어서 member와 상관없이 항상 실행돼요.
    println!("주문 접수");
    // 아래 쿠폰 안내 줄이 회원일 때만 실행되게 if 블록 안으로 옮기세요.
    // if 뒤의 조건이 true일 때만 중괄호 안을 실행해요. 중괄호는 생략할 수 없어요.
    if member {
        // member가 false면 이 줄을 건너뛰고 닫는 중괄호 뒤로 가요.
        println!("회원 쿠폰이 있어요");
    }
}

