tasks.solution:
fn main() {
    // 주문 금액이 30,000원보다 많으면 무료 배송이에요.
    // 32_000처럼 밑줄로 끊어 써도 값은 32000이에요. 출력에는 밑줄이 없어요.
    let total = 32_000;
    // true 자리에 total과 30_000을 비교하는 식을 쓰세요.
    // total > 30_000은 total이 더 클 때만 true예요. 코드 안 숫자에는 쉼표를 쓰지 않아요.
    if total > 30_000 {
        // 비교 결과가 false면 이 줄을 건너뛰어요.
        println!("무료 배송");
    }
    // 금액 출력은 if 밖이라 언제나 실행돼요.
    println!("주문 금액: {total}");
}

tasks.starter_code:
fn main() {
    // 30,000원보다 많으면 무료 배송, 아니면 배송비 3000원이에요.
    let total = 20_000;
    if total > 30_000 {
        println!("무료 배송");
    }
    // 위 if 블록의 닫는 중괄호 뒤에 else 갈래를 붙이세요.
    println!("주문 금액: {total}");
}

tasks.solution:
fn main() {
    // 30,000원보다 많으면 무료 배송, 아니면 배송비 3000원이에요.
    // 채점은 이 값을 32_000으로 바꿔서도 실행해요.
    let total = 20_000;
    // 조건이 true면 첫 갈래, false면 else 갈래 하나만 실행돼요.
    if total > 30_000 {
        println!("무료 배송");
    } else {
        // 이 줄을 if 블록 밖에 그냥 쓰면 32,000원일 때도 실행돼요.
        println!("배송비 3000원");
    }
    // 위 if 블록의 닫는 중괄호 뒤에 else 갈래를 붙이세요.
    // 주문 금액은 어느 갈래를 지나든 출력돼요.
    println!("주문 금액: {total}");
}

