tasks.solution:
fn main() {
    // 배송비를 조건으로 골라 fee에 담아요.
    // 채점은 이 값을 20_000으로 바꿔서도 실행해요.
    let total = 32_000;
    // 3000 자리에 금액에 따라 0이나 3000이 되는 if 식을 쓰세요.
    // if 식은 갈래 하나의 값이 돼요. else가 없으면 false일 때 담을 값이 없어 E0317이 나요.
    let fee = if total > 30_000 { 0 } else { 3000 };
    // fee에는 고른 정수 하나가 담겨 있어서 바로 더할 수 있어요.
    let pay = total + fee;
    println!("배송비: {fee}");
    println!("결제 금액: {pay}");
}

