fn main() {
    // 보낼 상자 수예요.
    // 채점은 이 값을 5로 바꿔서도 실행해요.
    let boxes = 3;
    // 상자 번호가 1번부터 상자 수까지 나오게 범위를 고치세요.
    // a..b는 b를 빼고 반복해요. 끝에 1을 더해야 boxes까지 들어가요.
    // 끝을 포함하는 1..=boxes로 써도 같은 번호가 나와요.
    for number in 1..boxes + 1 {
        // 반복마다 number에 다음 번호가 담겨요.
        println!("상자 {number}");
    }
}

