tasks.solution:
fn main() {
    // 상자 하나의 배송비예요.
    // 채점은 이 값을 바꿔서도 실행해요.
    let fee = 3000;
    // 배송비 합계는 반복 밖에서 0으로 시작해요.
    // 반복 안에서 만들면 돌 때마다 0으로 다시 시작해 합계가 쌓이지 않아요.
    let mut sum = 0;
    // 상자 1, 2, 3에 대해 한 번씩, 모두 세 번 돌아요.
    for number in 1..4 {
        // 0 자리를 fee로 바꿔 이번 상자의 배송비를 더하세요.
        // +=는 지금까지의 합계에 fee를 더해 다시 sum에 넣어요.
        sum += fee;
        // 더한 직후의 합계가 상자마다 한 줄씩 찍혀요.
        println!("상자 {number}까지 배송비: {sum}");
    }
}

